				if (m.count) {
					const btn = smallBtn('Reclaim', true, () => { btn.disabled = true; vscode.postMessage({ type: 'reclaimStuck' }); });
					b.replaceChildren(el('span', '', m.fee + ' LCAI from ' + m.count + ' stalled job' + (m.count === 1 ? '' : 's') + ' can be reclaimed'), btn);
				}
